create or replace function public.notify_super_admin_payment_event() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if tg_table_name='repayment_transactions' and new.status in ('allocated','partially_allocated','unapplied') then perform public.create_staff_notifications(new.institution_id,'staff.manage','Payment received','A verified customer payment of KES '||to_char(new.amount,'FM999,999,999,990.00')||' was received.','urgent','payment-received:'||new.id,new.id,null,true); elsif tg_table_name='loan_accounts' and new.status='active' and old.status is distinct from 'active' then perform public.create_staff_notifications(new.institution_id,'staff.manage','Loan disbursed','A loan was successfully disbursed and is now active.','urgent','loan-disbursed:'||new.id,new.id,null,true); end if; return new; end $$;
drop trigger if exists super_admin_payment_alerts_repayment on public.repayment_transactions;
create trigger super_admin_payment_alerts_repayment after insert or update of status on public.repayment_transactions for each row execute function public.notify_super_admin_payment_event();
drop trigger if exists super_admin_payment_alerts_disbursement on public.loan_accounts;
create trigger super_admin_payment_alerts_disbursement after update of status on public.loan_accounts for each row execute function public.notify_super_admin_payment_event();
notify pgrst,'reload schema';
